"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[39844],{39844:function(t){t.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/7eb23f0631873ded35bf2fb3e99f182d.jpg\\"\\n  title=\\"수월경화\\"\\n  cuisine=\\"카페\\"\\n  address=\\"부산광역시 해운대구 송정중앙로6번길 188\\"\\n  rating=3\\n  tags=\\"cafe\\"\\n/>\\n</center>\\n\\n## Review\\n`해변관광열차`를 타고 이동해서 방문한 곳이다.  \\n크게 기대하고 찾아간 곳은 아니었지만, 생각보다 뷰가 참 좋은 곳이었다.  \\n\\n들어가는 입구에는 카페의 정체성을 보여주는 장식이 되어 있었다.  \\n입구의 분위기에 비해 내부는 생각보다 깔끔하고 모던한 느낌이었다.  \\n\\n계란 노른자를 띄워 준다는 문구에 망설임 없이 `쌍화탕`과 `아이스 아메리카노`를 주문했다.  \\n\\n`쌍화탕`은 조금 달달한 편이고, 견과류가 아주 듬뿍 들어 있었다.  \\n개인적으로는 조금 덜 달아도 될 것 같다고 생각했다.  \\n\\n오히려 커피 쪽이 산미도 적고 고소해서 내 취향에 더 잘 맞았다.  \\n\\n바다를 보며 멍때리기 좋은 자리에 앉아 여유로운 시간을 보냈다.\\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/4cc1030126f60fcecfd53aa64b1bd0ff.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"수월경화\\">\\n<img src=\\"/assets/snippets/location/cd4476741ab45af6c414a9ec071bcb71.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"수월경화\\">\\n<img src=\\"/assets/snippets/location/5da6a787c11868413da273a0d24b4407.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"수월경화\\">\\n<img src=\\"/assets/snippets/location/f0f2c092266183aaf6989cdb6cede80f.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"수월경화\\">\\n</pictures>\\n"}')}}]);